 Person MakePerson(Vector2 p,bool zombie,int id){p=ResolveSolidPosition(p);var a=new Person{p=p,spawn=p,id=id,goal=p,phase=id*.7f};if(zombie){a.speed=id%3==1?2.55f:id%3==2?2.1f:3.35f;a.hp=id%3==1?195:id%3==2?90:140;}a.maxHp=a.hp;a.root=new GameObject(zombie?"Infected":"Survivor").transform;a.root.position=V(p);a.visual=a.root.gameObject.AddComponent<DistrictActorVisual>();if(a.visual.Initialize(zombie,id)){
 var grip=new GameObject("Tool grip").transform;var hand=a.visual.Hand;grip.SetParent(hand?hand:a.root,false);if(hand){Vector3 scale=hand.lossyScale;grip.localScale=new Vector3(1/Mathf.Abs(scale.x),1/Mathf.Abs(scale.y),1/Mathf.Abs(scale.z));}else grip.localPosition=new Vector3(.32f,1.1f,.2f);a.armR=grip;return a;}Destroy(a.visual);a.visual=null;
 Color coat=zombie?new Color(.31f,.38f,.29f):new Color(.25f,.43f,.55f);Color skin=zombie?new Color(.52f,.57f,.41f):new Color(.73f,.57f,.42f);Cube("Torso",new Vector3(0,1.15f,0),new Vector3(.55f,.65f,.32f),coat,a.root);Cube("Head",new Vector3(0,1.72f,0),new Vector3(.34f,.4f,.34f),skin,a.root);Cube("Hair",new Vector3(0,1.93f,0),new Vector3(.35f,.1f,.35f),new Color(.14f,.14f,.12f),a.root);a.armL=Cube("Left arm",new Vector3(-.39f,1.08f,0),new Vector3(.19f,.7f,.2f),coat,a.root).transform;a.armR=Cube("Right arm",new Vector3(.39f,1.08f,0),new Vector3(.19f,.7f,.2f),coat,a.root).transform;a.legL=Cube("Left leg",new Vector3(-.17f,.38f,0),new Vector3(.22f,.75f,.25f),new Color(.17f,.20f,.23f),a.root).transform;a.legR=Cube("Right leg",new Vector3(.17f,.38f,0),new Vector3(.22f,.75f,.25f),new Color(.17f,.20f,.23f),a.root).transform;return a;}
 bool Blocked(Vector2 p){if(!InsideWorld(p)||SolidBlocked(p))return true;foreach(var b in barriers)if(b.active&&new Rect(b.rect.x-.28f,b.rect.y-.28f,b.rect.width+.56f,b.rect.height+.56f).Contains(p))return true;return false;}
 float FrameDelta=>Mathf.Min(Time.deltaTime,.25f);
 Vector2 Move(Vector2 p,Vector2 d){int steps=Mathf.Max(1,Mathf.CeilToInt(d.magnitude/.12f));Vector2 step=d/steps;for(int i=0;i<steps;i++){Vector2 q=p+new Vector2(step.x,0);if(!Blocked(q))p=q;q=p+new Vector2(0,step.y);if(!Blocked(q))p=q;}return p;}
 bool Sight(Vector2 a,Vector2 b){int steps=Mathf.CeilToInt(Vector2.Distance(a,b)*2);for(int i=1;i<steps;i++)if(SightBlocked(Vector2.Lerp(a,b,(float)i/steps)))return false;return true;}

 void Alert(Vector2 p,float radius){HearNoise(p,radius); }
 void Say(string s){notice=s;noticeTime=s.StartsWith("ЗАПИСКА")?12:5;}
 void Door(Home h){h.open=!h.open;Alert(h.p+Vector2.down*4,9);Say(h.open?"Открываю дверь. Закрой её за собой.":"Закрываю дверь. Проём должен быть свободен.");foley.Door(V(h.p+Vector2.down*4,1),h.open);}
 void Use(){if(approachHome!=null){CancelSearch();return;}if(Climbing){if(climbTime<climbApproach)ClearWindowClimb(false);return;}if(searchSlot>=0){CancelSearch();return;}if(medicalAction!=MedicalAction.None)return;if(UseTelevision())return;if(UseFortification())return;if(UseBackExit())return;if(UseExploration())return;if(UseLifeFind())return;if(UseEngine())return;if(UseSupply())return;if(UseClothingFind())return;if(UseBackpackFind())return;if(UseWaterFind())return;if(UseCistern())return;if(UseDepot())return;if(Vector2.Distance(hero.p,refuge)<4){if(!campEstablished){if(HasAnyMeal&&bandages>0&&SpendCampMeal()){campEstablished=true;bandages--;health=Mathf.Min(100,health+25);Save();Say("Убежище обустроено. Исследование продолжается. Возвращайся с едой, чтобы восстановиться.");}else Say("Для обустройства убежища нужны еда и бинт. Радио искать необязательно.");}else if(HasAnyMeal&&health<100&&SpendCampMeal()){health=Mathf.Min(100,health+25);Save();Say("Отдых и еда: +25 здоровья. Можно идти дальше.");}else Say("Твоё убежище. Для восстановления принеси еду. Исследуй оставшиеся дома.");return;}if(Vector2.Distance(hero.p,radioPos)<2&&Sight(hero.p,radioPos)){ToggleRadio();return;}foreach(var h in homes)if(h.built&&Vector2.Distance(hero.p,h.p+Vector2.down*4)<2){Door(h);return;}if(current!=null){int slot=FocusedStorageSlot();if(slot>=0){InteractStorage(current,slot);return;}}if(current!=null&&current.note!=null&&Vector2.Distance(hero.p,current.p+new Vector2(-2,0))<1.7f){Say(current.note);return;}Say("Подойди к двери, шкафу, записке или радио");}
 void Loot(Home h,int i){RevealStorage(h,i);}
 void Animate(Person p,Vector2 movement,bool zombie,float strike){if(!zombie&&AnimateWindowClimb())return;p.root.position=V(p.p);Vector2 facing=!zombie&&approachTurning?Vector2.up:!zombie&&(strike>0||pcAiming)?(strike>0?heroStrikeDirection:face):movement;if(!zombie&&p.visual)p.visual.Face(V(facing),movement.magnitude/Mathf.Max(.001f,FrameDelta),Time.deltaTime);else if(facing.sqrMagnitude>.000001f)p.root.rotation=Quaternion.Slerp(p.root.rotation,Quaternion.LookRotation(V(facing)),Time.deltaTime*12);
 if(p.visual){if(!zombie){p.visual.ReverseWalk=pcAiming&&Vector2.Dot(movement,face)<-movement.magnitude*.3f;p.visual.SetStorageSearch(searchSlot>=0?searchTime:-1);SetStorageContact();p.visual.SetSearching(FortHandsBusy||cacheSearching||searchSlot>=0||medicalAction==MedicalAction.Read||medicalAction==MedicalAction.Make||medicalAction==MedicalAction.Salvage);p.visual.SetSurvivalPose(SurvivalPose(),medicalAction==MedicalAction.None?0:medicalTime/MedicalDuration(medicalAction));}float speed=movement.magnitude/Mathf.Max(.001f,FrameDelta);p.visual.Tick(strike>0?0:speed,Time.deltaTime,Vector2.Distance(p.p,hero.p),!zombie||Sight(p.p,hero.p));return;}
